contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool dummy) public payable {
        require(c.owner() == address(this));
        address before = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(!reverted && afterOwner == address(this));
    }
    receive() external payable {}
}

