// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(bool dummy) internal {
        vm.assume(c.owner() == address(this));
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue(!reverted && afterOwner == address(this));
    }

    function testFuzz_run(bool dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
